## Analytical caution

Migration to a private channel should not automatically be treated as proof of violent radicalization. It is better understood as a **high-risk transition in the socialization process**. Researchers should distinguish among:

- curiosity;
- ideological agreement;
- social embeddedness;
- behavioral commitment;
- mobilization or violence.

A useful summary is: **the funnel moves from low-cost exposure, to personalized grievance, to alternative social proof, to a protected private identity, and finally to a sense of moral obligation.**

Below is a complete, standalone implementation. Save it as **`RedBlackTree.java`**. It uses unique keys: inserting a duplicate returns `false`, and deletion returns whether the key was found.

```java
import java.util.ArrayList;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.Objects;

/**
 * Red-Black Tree implementation.
 *
 * Time complexity:
 *   - Search:    O(log n)
 *   - Insertion: O(log n)
 *   - Deletion:  O(log n)
 *
 * Null keys are not allowed. Duplicate keys are rejected.
 */
public final class RedBlackTree<K extends Comparable<? super K>, V> {

    private enum Color {
        RED,
        BLACK
    }

    /**
     * A node in the red-black tree.
     */
    private static final class Node<K, V> {
        final K key;
        final V value;

        Color color;
        Node<K, V> left;
        Node<K, V> right;
        Node<K, V> parent;

        Node(K key, V value, Color color) {
            this.key = key;
            this.value = value;
            this.color = color;
        }
    }

    /*
     * NIL represents every absent child. Using a sentinel avoids
     * repeated null checks in the rotation and balancing code.
     */
    private final Node<K, V> nil;

    private Node<K, V> root;
    private int size;

    public RedBlackTree() {
        nil = new Node<>(null, null, Color.BLACK);
        nil.left = nil;
        nil.right = nil;
        nil.parent = nil;

        root = nil;
    }

    /**
     * Inserts a key-value pair.
     *
     * @return true if inserted, or false if the key already exists
     */
    public boolean insert(K key, V value) {
        Objects.requireNonNull(key, "Key cannot be null");

        if (findNode(key) != nil) {
            return false;
        }

        Node<K, V> parent = nil;
        Node<K, V> current = root;

        // Find the insertion position.
        while (current != nil) {
            parent = current;

            if (key.compareTo(current.key) < 0) {
                current = current.left;
            } else {
                current = current.right;
            }
        }

        Node<K, V> newNode = new Node<>(key, value, Color.RED);
        newNode.left = nil;
        newNode.right = nil;
        newNode.parent = parent;

        if (parent == nil) {
            root = newNode;
        } else if (key.compareTo(parent.key) < 0) {
            parent.left = newNode;
        } else {
            parent.right = newNode;
        }

        size++;
        insertFixUp(newNode);
        return true;
    }

    /**
     * Restores red-black properties after insertion.
     */
    private void insertFixUp(Node<K, V> node) {
        while (node.parent.color == Color.RED) {
            Node<K, V> parent = node.parent;
            Node<K, V> grandparent = parent.parent;

            if (parent == grandparent.left) {
                Node<K, V> uncle = grandparent.right;

                // Case 1: parent and uncle are both red.
                if (uncle.color == Color.RED) {
                    parent.color = Color.BLACK;
                    uncle.color = Color.BLACK;
                    grandparent.color = Color.RED;
                    node = grandparent;
                } else {
                    // Case 2: node is the right child.
                    if (node == parent.right) {
                        node = parent;
                        rotateLeft(node);
                        parent = node.parent;
                    }

                    // Case 3: node is the left child.
                    parent.color = Color.BLACK;
                    grandparent.color = Color.RED;
                    rotateRight(grandparent);
                }
            } else {
                // Symmetric cases when the parent is a right child.
                Node<K, V> uncle = grandparent.left;

                if (uncle.color == Color.RED) {
                    parent.color = Color.BLACK;
                    uncle.color = Color.BLACK;
                    grandparent.color = Color.RED;
                    node = grandparent;
                } else {
                    if (node == parent.left) {
                        node = parent;
                        rotateRight(node);
                        parent = node.parent;
                    }

                    parent.color = Color.BLACK;
                    grandparent.color = Color.RED;
                    rotateLeft(grandparent);
                }
            }
        }

        // The root must always be black.
        root.color = Color.BLACK;
    }

    /**
     * Deletes the node containing the specified key.
     *
     * @return true if the key was found and deleted
     */
    public boolean delete(K key) {
        Objects.requireNonNull(key, "Key cannot be null");

        Node<K, V> nodeToDelete = findNode(key);

        if (nodeToDelete == nil) {
            return false;
        }

        Node<K, V> movedNode = nodeToDelete;
        Node<K, V> replacement;
        Color removedColor = movedNode.color;

        if (nodeToDelete.left == nil) {
            // The node has at most one child.
            replacement = nodeToDelete.right;
            transplant(nodeToDelete, nodeToDelete.right);
        } else if (nodeToDelete.right == nil) {
            // The node has at most one child.
            replacement = nodeToDelete.left;
            transplant(nodeToDelete, nodeToDelete.left);
        } else {
            // Two children: use the in-order successor.
            movedNode = minimum(nodeToDelete.right);
            removedColor = movedNode.color;
            replacement = movedNode.right;

            if (movedNode.parent == nodeToDelete) {
                // The replacement remains the right child of movedNode.
                replacement.parent = movedNode;
            } else {
                transplant(movedNode, movedNode.right);
                movedNode.right = nodeToDelete.right;
                movedNode.right.parent = movedNode;
            }

            transplant(nodeToDelete, movedNode);
            movedNode.left = nodeToDelete.left;
            movedNode.left.parent = movedNode;
            movedNode.color = nodeToDelete.color;
        }

        // Removing a black node may create a temporary double-black problem.
        if (removedColor == Color.BLACK) {
            deleteFixUp(replacement);
        }

        root.color = Color.BLACK;
        nil.parent = nil;
        size--;

        return true;
    }

    /**
     * Restores red-black properties after deletion.
     */
    private void deleteFixUp(Node<K, V> node) {
        while (node != root && node.color == Color.BLACK) {
            if (node == node.parent.left) {
                Node<K, V> sibling = node.parent.right;

                // Case 1: sibling is red.
                if (sibling.color == Color.RED) {
                    sibling.color = Color.BLACK;
                    node.parent.color = Color.RED;
                    rotateLeft(node.parent);
                    sibling = node.parent.right;
                }

                // Case 2: sibling and both of its children are black.
                if (sibling.left.color == Color.BLACK
                        && sibling.right.color == Color.BLACK) {
                    sibling.color = Color.RED;
                    node = node.parent;
                } else {
                    // Case 3: sibling's right child is black.
                    if (sibling.right.color == Color.BLACK) {
                        sibling.left.color = Color.BLACK;
                        sibling.color = Color.RED;
                        rotateRight(sibling);
                        sibling = node.parent.right;
                    }

                    // Case 4: sibling's right child is red.
                    sibling.color = node.parent.color;
                    node.parent.color = Color.BLACK;
                    sibling.right.color = Color.BLACK;
                    rotateLeft(node.parent);
                    node = root;
                }
            } else {
                // Symmetric cases when node is a right child.
                Node<K, V> sibling = node.parent.left;

                if (sibling.color == Color.RED) {
                    sibling.color = Color.BLACK;
                    node.parent.color = Color.RED;
                    rotateRight(node.parent);
                    sibling = node.parent.left;
                }

                if (sibling.left.color == Color.BLACK
                        && sibling.right.color == Color.BLACK) {
                    sibling.color = Color.RED;
                    node = node.parent;
                } else {
                    if (sibling.left.color == Color.BLACK) {
                        sibling.right.color = Color.BLACK;
                        sibling.color = Color.RED;
                        rotateLeft(sibling);
                        sibling = node.parent.left;
                    }

                    sibling.color = node.parent.color;
                    node.parent.color = Color.BLACK;
                    sibling.left.color = Color.BLACK;
                    rotateRight(node.parent);
                    node = root;
                }
            }
        }

        node.color = Color.BLACK;
    }

    /**
     * Replaces one subtree with another subtree.
     */
    private void transplant(Node<K, V> oldRoot, Node<K, V> replacement) {
        if (oldRoot.parent == nil) {
            root = replacement;
        } else if (oldRoot == oldRoot.parent.left) {
            oldRoot.parent.left = replacement;
        } else {
            oldRoot.parent.right = replacement;
        }

        replacement.parent = oldRoot.parent;
    }

    /**
     * Returns the node with the smallest key in a subtree.
     */
    private Node<K, V> minimum(Node<K, V> node) {
        while (node.left != nil) {
            node = node.left;
        }
        return node;
    }

    /**
     * Performs a left rotation around the given node.
     */
    private void rotateLeft(Node<K, V> node) {
        Node<K, V> rightChild = node.right;

        node.right = rightChild.left;

        if (rightChild.left != nil) {
            rightChild.left.parent = node;
        }

        rightChild.parent = node.parent;

        if (node.parent == nil) {
            root = rightChild;
        } else if (node == node.parent.left) {
            node.parent.left = rightChild;
        } else {
            node.parent.right = rightChild;
        }

        rightChild.left = node;
        node.parent = rightChild;
    }

    /**
     * Performs a right rotation around the given node.
     */
    private void rotateRight(Node<K, V> node) {
        Node<K, V> leftChild = node.left;

        node.left = leftChild.right;

        if (leftChild.right != nil) {
            leftChild.right.parent = node;
        }

        leftChild.parent = node.parent;

        if (node.parent == nil) {
            root = leftChild;
        } else if (node == node.parent.right) {
            node.parent.right = leftChild;
        } else {
            node.parent.left = leftChild;
        }

        leftChild.right = node;
        node.parent = leftChild;
    }

    /**
     * Finds the node containing the specified key.
     */
    private Node<K, V> findNode(K key) {
        Node<K, V> current = root;

        while (current != nil) {
            int comparison = key.compareTo(current.key);

            if (comparison == 0) {
                return current;
            } else if (comparison < 0) {
                current = current.left;
            } else {
                current = current.right;
            }
        }

        return nil;
    }

    /**
     * Returns the value associated with key.
     */
    public V get(K key) {
        Objects.requireNonNull(key, "Key cannot be null");

        Node<K, V> node = findNode(key);

        if (node == nil) {
            throw new NoSuchElementException("Key is not present: " + key);
        }

        return node.value;
    }

    public boolean containsKey(K key) {
        Objects.requireNonNull(key, "Key cannot be null");
        return findNode(key) != nil;
    }

    public int size() {
        return size;
    }

    public boolean isEmpty() {
        return size == 0;
    }

    /**
     * Returns all keys in sorted order.
     */
    public List<K> keysInOrder() {
        List<K> result = new ArrayList<>();
        collectInOrder(root, result);
        return result;
    }

    private void collectInOrder(Node<K, V> node, List<K> result) {
        if (node == nil) {
            return;
        }

        collectInOrder(node.left, result);
        result.add(node.key);
        collectInOrder(node.right, result);
    }

    /**
     * Checks all red-black tree invariants. This is mainly useful for
     * testing and debugging.
     */
    public boolean isValid() {
        if (root.color != Color.BLACK) {
            return false;
        }

        if (root != nil && root.parent != nil) {
            return false;
        }

        return validateNode(root, null, null) != -1;
    }

    /**
     * Validates a subtree and returns its black height.
     * Returns -1 if an invariant is violated.
     */
    private int validateNode(Node<K, V> node, K lowerBound, K upperBound) {
        if (node == nil) {
            return 1;
        }

        if (lowerBound != null && node.key.compareTo(lowerBound) <= 0) {
            return -1;
        }

        if (upperBound != null && node.key.compareTo(upperBound) >= 0) {
            return -1;
        }

        if (node.left.parent != node || node.right.parent != node) {
            return -1;
        }

        if (node.color == Color.RED
                && (node.left.color == Color.RED
                || node.right.color == Color.RED)) {
            return -1;
        }

        int leftBlackHeight = validateNode(node.left, lowerBound, node.key);

        if (leftBlackHeight == -1) {
            return -1;
        }

        int rightBlackHeight = validateNode(node.right, node.key, upperBound);

        if (rightBlackHeight == -1) {
            return -1;
        }

        if (leftBlackHeight != rightBlackHeight) {
            return -1;
        }

        return leftBlackHeight + (node.color == Color.BLACK ? 1 : 0);
    }

    /**
     * Example program demonstrating insertion and deletion.
     */
    public static void main(String[] args) {
        RedBlackTree<Integer, String> tree = new RedBlackTree<>();

        int[] keys = {10, 20, 30, 15, 25, 5, 1};

        for (int key : keys) {
            tree.insert(key, "Value " + key);
        }

        System.out.println("After insertion: " + tree.keysInOrder());
        System.out.println("Tree is valid: " + tree.isValid());
        System.out.println("Value at key 15: " + tree.get(15));

        System.out.println("Deleted key 20: " + tree.delete(20));
        System.out.println("Deleted key 5: " + tree.delete(5));
        System.out.println("Deleted key 30: " + tree.delete(30));

        System.out.println("After deletion: " + tree.keysInOrder());
        System.out.println("Tree is valid: " + tree.isValid());
        System.out.println("Tree size: " + tree.size());
    }
}
